import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.C8R-a4p3.js";var i=JSON.parse(`{"title":"This Portfolio: Four Languages, One Repo","description":"The meta-story: how this very site was specified, cloned from easy-vibe's design system, translated into four languages and shipped by an agent team.","frontmatter":{"title":"This Portfolio: Four Languages, One Repo","description":"The meta-story: how this very site was specified, cloned from easy-vibe's design system, translated into four languages and shipped by an agent team."},"headers":[],"relativePath":"en/vibe-stories/story-4/index.md","filePath":"en/vibe-stories/story-4/index.md"}`),a={name:`en/vibe-stories/story-4/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="this-portfolio-four-languages-one-repo" tabindex="-1">This Portfolio: Four Languages, One Repo <a class="header-anchor" href="#this-portfolio-four-languages-one-repo" aria-label="Permalink to “This Portfolio: Four Languages, One Repo”">​</a></h1><p>You are looking at the most self-referential project in my portfolio: <strong>this website</strong>. It is a faithful rebuild of the <a href="https://datawhalechina.github.io/easy-vibe/en/" target="_blank" rel="noreferrer">easy-vibe</a> design system — the exact VitePress theme, layout and behavior — with every text and image replaced by my own content, in <strong>four languages</strong>: English, Persian, Arabic and Spanish.</p><h2 id="why-clone-a-course-site" tabindex="-1">Why clone a course site? <a class="header-anchor" href="#why-clone-a-course-site" aria-label="Permalink to “Why clone a course site?”">​</a></h2><p>Because it is honest about what good engineering is: find something excellent, understand it completely, then adapt it with respect. The theme&#39;s Apple-style home, its glass navigation, the typing tagline, the MacBook-framed story carousel — all of it was studied, ported and re-anchored to a new engine version, then filled with a life it was never written for.</p><h2 id="what-made-it-non-trivial" tabindex="-1">What made it non-trivial <a class="header-anchor" href="#what-made-it-non-trivial" aria-label="Permalink to “What made it non-trivial”">​</a></h2><ul><li><strong>Four locales with RTL</strong> — Persian and Arabic flip typography, padding, icons and carousel direction; only code blocks stay LTR.</li><li><strong>Custom wordmark</strong> — the script &quot;Usf&quot; logo is generated from a real font into SVG paths so the animated welcome screen could keep its draw-on effect.</li><li><strong>Fourteen new illustrations</strong> — every card and story cover generated to match the theme&#39;s pastel aesthetic.</li><li><strong>Agent-team assembly</strong> — theme port, content, translations and deployment ran as parallel agent workstreams, coordinated the <a href="/Usf/en/agentic/hermes/">Hermes way</a>.</li></ul><p>The source of truth lives at <a href="https://github.com/Godde3s/Usf" target="_blank" rel="noreferrer">github.com/Godde3s/Usf</a> — public, naturally. If you are reading this on the live site, the deploy pipeline worked; if you are reading it on GitHub, the pipeline is one <code>vitepress build</code> away.</p>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};